/**
 * Inter (latin subset) TTFs for invoice PDF rendering, inlined as base64.
 *
 * Embedded instead of pdf-lib's standard Helvetica because non-embedded
 * standard fonts render the euro sign with a wrong advance width in some
 * viewers (notably macOS Quartz/Preview), overlapping the digits. Embedding
 * with `subset: true` keeps the generated PDF small (~6KB of font data).
 *
 * Coverage is the Google Fonts "latin" subset (ASCII + Latin-1 + common
 * punctuation) — same practical coverage as the previous WinAnsi setup,
 * but unsupported characters render as .notdef instead of throwing.
 *
 * Source: https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-{400,700}-normal.ttf
 * Regenerate with: base64 -i <ttf> | tr -d '\n'
 */

export const INTER_REGULAR_TTF_BASE64 =
  "";

export const INTER_BOLD_TTF_BASE64 =
  "";
